import {readFile,writeFile} from 'node:fs/promises';
export const workerModules=['limits','rational','xml','import','core','worker'];
export async function workerSource(){const parts=[];for(const name of workerModules){const text=await readFile(`src/${name}.mjs`,'utf8');parts.push(text.replace(/^import .*;\s*$/gm,'').replace(/^export \{[^}]+\};\s*$/gm,'').replace(/\bexport (?=(?:const|class|function|async function)\b)/g,''));}return '"use strict";\n'+parts.join('\n');}
export async function writeWorker(){await writeFile('src/worker-source.mjs','// Generated by scripts/worker-bundle.mjs. Do not edit by hand.\nexport const WORKER_SOURCE='+JSON.stringify(await workerSource())+';\n');}
